func _kill_feel_consume_budget() -> bool:
				var now = OS.get_ticks_msec()
				var budget = GameState.get_global(KILL_FEEL_BUDGET_KEY)
				if budget == null or now - budget.get("start_ms", 0) > KILL_FEEL_CLUSTER_WINDOW_MS:
								budget = {"start_ms": now, "count": 0}
				budget["count"] = budget.get("count", 0) + 1
				GameState.set_global(KILL_FEEL_BUDGET_KEY, budget)
				return budget["count"] <= KILL_FEEL_CLUSTER_BUDGET

func _kill_feel_apply_boost(tier):
				if tier <= 0:
								return
				if not _kill_feel_consume_budget():
								return
				if tier >= 2:
								var boss_burst = shatter.instance()
								boss_burst.global_position = global_position
								boss_burst.scale = Vector2(KILL_FEEL_BOOST_BOSS_SCALE, KILL_FEEL_BOOST_BOSS_SCALE)
								ground_layer.add_child(boss_burst)
